<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetVersion\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Document\SnippetVersion\Application\Usecase\Retrieve\SnippetVersionRetrieveUsecase;
use Civi\Lughauth\Features\Document\SnippetVersion\Application\Usecase\Retrieve\SnippetVersionRetrieveResult;

class SnippetVersionRetrieveController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly SnippetVersionRetrieveUsecase $retrieveUsecase,
    ) {
    }
    #[OA\Get(
        path: "/api/document/snippet-versions{uid}",
        tags: ["Snippet version"],
        description:"Create",
        parameters: [
               new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
          ],
        responses: [
              new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/SnippetVersionApiDTO")),
              new OA\Response(response: 404, description: "Not found"),
          ]
    )]
    public function retrieve(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Retrieve Snippet version");
        $span = $this->startSpan("Retrieve Snippet version");
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $result = $this->retrieveUsecase->retrieve($uid);
            $value = $this->mapSnippetVersion($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
                  ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapSnippetVersion(ServerRequestInterface $request, SnippetVersionRetrieveResult $value): SnippetVersionApiDTO
    {
        $this->logDebug("Map entity to output dto for Snippet version");
        $span = $this->startSpan("Map entity to output dto for Snippet version");
        try {
            $snippet = $value->getSnippet();
            $dto = new SnippetVersionApiDTO();
            $dto->uid = $value->getUid();
            $dto->snippet = $snippet ? ['$ref' => $snippet->uid()] : null;
            $dto->locale = $value->getLocale();
            $dto->subject = $value->getSubject();
            $dto->contentHtml = $value->getContentHtml();
            $dto->contentText = $value->getContentText();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
